private ProcessResult runMaven(Path pomDir) throws IOException, InterruptedException {
    Process process = new ProcessBuilder("mvn", "package", "-DskipTests")
            .directory(pomDir.toFile())
            .redirectErrorStream(true)
            .start();
    StringBuilder output = new StringBuilder();
    Thread reader = new Thread(() -> {
        try (BufferedReader br = new BufferedReader(new InputStreamReader(process.getInputStream()))) {
            String line;
            while ((line = br.readLine()) != null) {
                synchronized (output) {
                    output.append(line).append('\n');
                }
            }
        } catch (IOException ignored) {
        }
    });
    reader.setDaemon(true);
    reader.start();

    boolean exited = process.waitFor(BUILD_TIMEOUT_SECONDS, TimeUnit.SECONDS);
    if (!exited) {
        process.destroy();
        if (!process.waitFor(5, TimeUnit.SECONDS)) {
            process.destroyForcibly();
        }
        process.waitFor();
    }
    reader.join(5000);
    String out;
    synchronized (output) {
        out = output.toString();
    }
    return new ProcessResult(exited ? process.exitValue() : -1, out, !exited);
}
```

