public Build triggerBuild(Long projectId, String sourceZip, Long userId) {
    Build build = new Build();
    build.setProjectId(projectId);
    build.setStatus("BUILDING");
    build.setTriggeredBy(userId);
    build.setCreatedAt(LocalDateTime.now());
    try {
        buildMapper.insert(build);
        if (sourceZip == null || sourceZip.isBlank()) {
            return finish(build, "FAILED", null, "Empty source archive; the build was not run.");
        }
        byte[] zipBytes = Base64.getDecoder().decode(sourceZip);
        Path buildDir = Paths.get(BUILD_ROOT, String.valueOf(build.getId()));
        extractZip(zipBytes, buildDir);
        Path pomDir = locatePomDirectory(buildDir);
        if (pomDir == null) {
            return finish(build, "FAILED", null, "pom.xml descriptor not found at the archive root or in an immediate subdirectory.");
        }
        ProcessResult result = runMaven(pomDir);
        if (result.timedOut) {
            return finish(build, "FAILED", null, "Build timed out after " + BUILD_TIMEOUT_SECONDS + "s; child process terminated.\n" + result.output);
        }
        if (result.exitCode == 0) {
            return finish(build, "SUCCESS", findJar(pomDir.resolve("target").toFile()), result.output);
        }
        return finish(build, "FAILED", null, result.output);
    } catch (Exception e) {
        try {
            return finish(build, "FAILED", null, "Build pipeline error: " + e);
        } catch (Exception ignored) {
            build.setStatus("FAILED");
            build.setLogOutput("Build pipeline error: " + e);
            build.setFinishedAt(LocalDateTime.now());
            return build;
        }
    }
}
